// Top-customers report for the finance dashboard.
// orders: [{ id, customerId, status, amountCents, currency: 'USD' | 'EUR', createdAt: ISO-8601 string }]
const EUR_TO_USD = 1.08;

function byRank(a, b) {
  if (a.spendCents !== b.spendCents) return b.spendCents - a.spendCents;
  if (a.firstOrderAt !== b.firstOrderAt) return a.firstOrderAt < b.firstOrderAt ? -1 : 1;
  return a.customerId < b.customerId ? -1 : a.customerId > b.customerId ? 1 : 0;
}

function spendOf(order) {
  return order.currency === 'EUR' ? Math.round(order.amountCents * EUR_TO_USD) : order.amountCents;
}

function toReport(groups, limit) {
  return groups
    .filter((g) => g.spendCents > 0)
    .slice(0, limit)
    .map((g, i) => ({ rank: i + 1, ...g }));
}

// Fast path: O(n) grouping plus one sort at the end.
// When every customerId and createdAt is a string and every total is a finite number,
// byRank is a strict total order over the groups (customerIds are distinct), so a single
// final sort yields exactly the order the original sort-after-every-order loop produced.
// Anything else (malformed data) goes to summarizeExact, which replays the original algorithm.
function summarize(orders, limit = 10) {
  const seen = new Set();
  const byCustomer = new Map();
  const groups = [];
  for (const order of orders) {
    // Upstream retries can deliver the same order twice.
    if (seen.has(order.id)) continue;
    seen.add(order.id);
    if (order.status === 'refunded') continue;

    if (typeof order.customerId !== 'string' || typeof order.createdAt !== 'string') return summarizeExact(orders, limit);
    let group = byCustomer.get(order.customerId);
    if (!group) {
      group = { customerId: order.customerId, spendCents: 0, orderCount: 0, firstOrderAt: order.createdAt };
      byCustomer.set(order.customerId, group);
      groups.push(group);
    }
    group.orderCount++;
    if (order.createdAt < group.firstOrderAt) group.firstOrderAt = order.createdAt;
    if (order.status === 'paid') group.spendCents += spendOf(order);
  }
  for (const g of groups) {
    if (typeof g.spendCents !== 'number' || !Number.isFinite(g.spendCents)) return summarizeExact(orders, limit);
  }
  groups.sort(byRank);
  return toReport(groups, limit);
}

// The original algorithm (re-sorting after every order), kept for malformed input where
// the ranking comparator has ties or is inconsistent and the history of sorts matters.
function summarizeExact(orders, limit) {
  const seen = new Set(); // same SameValueZero semantics as Array#includes
  const groups = [];
  for (const order of orders) {
    if (seen.has(order.id)) continue;
    seen.add(order.id);
    if (order.status === 'refunded') continue;

    let group = groups.find((g) => g.customerId === order.customerId);
    if (!group) {
      group = { customerId: order.customerId, spendCents: 0, orderCount: 0, firstOrderAt: order.createdAt };
      groups.push(group);
    }
    group.orderCount++;
    if (order.createdAt < group.firstOrderAt) group.firstOrderAt = order.createdAt;
    if (order.status === 'paid') group.spendCents += spendOf(order);
    groups.sort(byRank);
  }
  return toReport(groups, limit);
}

module.exports = { summarize };
EOF

